			if (!oldItem) {
				this._attachments.set(item.id, item);
				added.push(item);
				this._watchAttachment(item);
				this._maybeResolveDirectoryImageCount(item);
			} else if (!equals(oldItem, item)) {
				this._fileWatchers.deleteAndDispose(item.id);
				this._attachments.set(item.id, item);
