private onDidChangeDirty(workingCopy: IWorkingCopy): void {
	if (this.suspended) {
		this.logService.warn(`[backup tracker] suspended, ignoring dirty change event`, workingCopy.resource.toString(), workingCopy.typeId);
		return;
	}

	if (workingCopy.isDirty()) {
		this.scheduleBackup(workingCopy);
	} else {
		this.discardBackup(workingCopy);
	}
}

private onDidChangeContent(workingCopy: IWorkingCopy): void {

	// Increment content version ID
	const contentVersionId = this.getContentVersion(workingCopy);
	this.mapWorkingCopyToContentVersion.set(workingCopy, contentVersionId + 1);

	// Check suspended
	if (this.suspended) {
		this.logService.warn(`[backup tracker] suspended, ignoring content change event`, workingCopy.resource.toString(), workingCopy.typeId);
		return;
	}

	// Schedule backup for modified working copies
	if (workingCopy.isModified()) {
		// this listener will make sure that the backup is
		// pushed out for as long as the user is still changing
		// the content of the working copy.
		this.scheduleBackup(workingCopy);
	}
}

private scheduleBackup(workingCopy: IWorkingCopy): void {

	// Clear any running backup operation
	this.cancelBackupOperation(workingCopy);

	this.logService.trace(`[backup tracker] scheduling backup`, workingCopy.resource.toString(), workingCopy.typeId);

	// Schedule new backup
	const workingCopyIdentifier = { resource: workingCopy.resource, typeId: workingCopy.typeId };
	const cts = new CancellationTokenSource();
	const handle = setTimeout(async () => {
		if (cts.token.isCancellationRequested) {
			return;
		}

		// Backup if modified
		if (workingCopy.isModified()) {
			this.logService.trace(`[backup tracker] creating backup`, workingCopy.resource.toString(), workingCopy.typeId);

			try {
				const backup = await workingCopy.backup(cts.token);
				if (cts.token.isCancellationRequested) {
					return;
				}

				if (workingCopy.isModified()) {
					this.logService.trace(`[backup tracker] storing backup`, workingCopy.resource.toString(), workingCopy.typeId);

					await this.workingCopyBackupService.backup(workingCopy, backup.content, this.getContentVersion(workingCopy), backup.meta, cts.token);
				}
			} catch (error) {
				this.logService.error(error);
			}
		}

		// Clear disposable unless we got canceled which would
		// indicate another operation has started meanwhile
		if (!cts.token.isCancellationRequested) {
			this.doClearPendingBackupOperation(workingCopyIdentifier);
		}
	}, this.getBackupScheduleDelay(workingCopy));

	// Keep in map for disposal as needed
	this.pendingBackupOperations.set(workingCopyIdentifier, {
		cancel: () => {
			this.logService.trace(`[backup tracker] clearing pending backup creation`, workingCopy.resource.toString(), workingCopy.typeId);

			cts.cancel();
		},
		disposable: toDisposable(() => {
			cts.dispose();
			clearTimeout(handle);
		})
	});
}

protected getBackupScheduleDelay(workingCopy: IWorkingCopy): number {
	if (typeof workingCopy.backupDelay === 'number') {
		return workingCopy.backupDelay; // respect working copy override
	}

	let backupScheduleDelay: 'default' | 'delayed';
	if (workingCopy.capabilities & WorkingCopyCapabilities.Untitled) {
		backupScheduleDelay = 'default'; // auto-save is never on for untitled working copies
	} else {
		backupScheduleDelay = this.filesConfigurationService.hasShortAutoSaveDelay(workingCopy.resource) ? 'delayed' : 'default';
	}

	return WorkingCopyBackupTracker.DEFAULT_BACKUP_SCHEDULE_DELAYS[backupScheduleDelay];
}

protected getContentVersion(workingCopy: IWorkingCopy): number {
	return this.mapWorkingCopyToContentVersion.get(workingCopy) || 0;
}

private discardBackup(workingCopy: IWorkingCopy): void {

	// Clear any running backup operation
	this.cancelBackupOperation(workingCopy);

	// Schedule backup discard asap
	const workingCopyIdentifier = { resource: workingCopy.resource, typeId: workingCopy.typeId };
	const cts = new CancellationTokenSource();
	this.doDiscardBackup(workingCopyIdentifier, cts);

	// Keep in map for disposal as needed
	this.pendingBackupOperations.set(workingCopyIdentifier, {
		cancel: () => {
			this.logService.trace(`[backup tracker] clearing pending backup discard`, workingCopy.resource.toString(), workingCopy.typeId);

			cts.cancel();
		},
		disposable: cts
	});
}

private async doDiscardBackup(workingCopyIdentifier: IWorkingCopyIdentifier, cts: CancellationTokenSource) {
	this.logService.trace(`[backup tracker] discarding backup`, workingCopyIdentifier.resource.toString(), workingCopyIdentifier.typeId);

	// Discard backup
	try {
		await this.workingCopyBackupService.discardBackup(workingCopyIdentifier, cts.token);
	} catch (error) {
		this.logService.error(error);
	}

	// Clear disposable unless we got canceled which would
	// indicate another operation has started meanwhile
	if (!cts.token.isCancellationRequested) {
		this.doClearPendingBackupOperation(workingCopyIdentifier);
	}
}

private cancelBackupOperation(workingCopy: IWorkingCopy): void {

	// Given a working copy we want to find the matching
	// identifier in our pending operations map because
	// we cannot use the working copy directly, as the
	// identifier might have different object identity.

	let workingCopyIdentifier: IWorkingCopyIdentifier | undefined = undefined;
	for (const [identifier] of this.pendingBackupOperations) {
		if (identifier.resource.toString() === workingCopy.resource.toString() && identifier.typeId === workingCopy.typeId) {
			workingCopyIdentifier = identifier;
			break;
		}

				// Backup exists
				const contentVersion = this.getContentVersion(workingCopy);
				if (this.workingCopyBackupService.hasBackupSync(workingCopy, contentVersion)) {
					backups.push(workingCopy);
				}

				// Backup does not exist
				else {
					const backup = await workingCopy.backup(token);
					if (token.isCancellationRequested) {
						return;
					}

					await this.workingCopyBackupService.backup(workingCopy, backup.content, contentVersion, backup.meta, token);
					if (token.isCancellationRequested) {
						return;
					}

					backups.push(workingCopy);
				}
			}));
		} catch (backupError) {
			error = backupError;
		}
	},
		localize('backupBeforeShutdownMessage', "Backing up editors with unsaved changes is taking a bit longer..."),
		localize('backupBeforeShutdownDetail', "Click 'Cancel' to stop waiting and to save or revert editors with unsaved changes.")
	);

	return { backups, error };
}

private async confirmBeforeShutdown(modifiedWorkingCopies: IWorkingCopy[]): Promise<boolean> {

	// Save
	const confirm = await this.fileDialogService.showSaveConfirm(modifiedWorkingCopies.map(workingCopy => workingCopy.name));
	if (confirm === ConfirmResult.SAVE) {
		const modifiedCountBeforeSave = this.workingCopyService.modifiedCount;

		try {
			await this.doSaveAllBeforeShutdown(modifiedWorkingCopies, SaveReason.EXPLICIT);
		} catch (error) {
			this.logService.error(`[backup tracker] error saving modified working copies: ${error}`); // guard against misbehaving saves, we handle remaining modified below
		}

		const savedWorkingCopies = modifiedCountBeforeSave - this.workingCopyService.modifiedCount;
		if (savedWorkingCopies < modifiedWorkingCopies.length) {
			return true; // veto (save failed or was canceled)
		}

		return this.noVeto(modifiedWorkingCopies); // no veto (modified saved)
	}

	// Don't Save
	else if (confirm === ConfirmResult.DONT_SAVE) {
		try {
			await this.doRevertAllBeforeShutdown(modifiedWorkingCopies);
		} catch (error) {
			this.logService.error(`[backup tracker] error reverting modified working copies: ${error}`); // do not block the shutdown on errors from revert
		}

		return this.noVeto(modifiedWorkingCopies); // no veto (modified reverted)
	}

	// Cancel
	return true; // veto (user canceled)
}

private doSaveAllBeforeShutdown(workingCopies: IWorkingCopy[], reason: SaveReason): Promise<void> {
	return this.withProgressAndCancellation(async () => {

		// Skip save participants on shutdown for performance reasons
		const saveOptions = { skipSaveParticipants: true, reason };

		// First save through the editor service if we save all to benefit
		// from some extras like switching to untitled modified editors before saving.
		let result: boolean | undefined = undefined;
		if (workingCopies.length === this.workingCopyService.modifiedCount) {
			result = (await this.editorService.saveAll({
				includeUntitled: { includeScratchpad: true },
				...saveOptions
			})).success;
		}

		// If we still have modified working copies, save those directly
		// unless the save was not successful (e.g. cancelled)
		if (result !== false) {
			await Promises.settled(workingCopies.map(workingCopy => workingCopy.isModified() ? workingCopy.save(saveOptions) : Promise.resolve(true)));
		}
	},
		localize('saveBeforeShutdown', "Saving editors with unsaved changes is taking a bit longer..."),
		undefined,
		// Do not pick `Dialog` as location for reporting progress if it is likely
		// that the save operation will itself open a dialog for asking for the
		// location to save to for untitled or scratchpad working copies.
		// https://github.com/microsoft/vscode-internalbacklog/issues/4943
		workingCopies.some(workingCopy => workingCopy.capabilities & WorkingCopyCapabilities.Untitled || workingCopy.capabilities & WorkingCopyCapabilities.Scratchpad) ? ProgressLocation.Window : ProgressLocation.Dialog);
}

private doRevertAllBeforeShutdown(modifiedWorkingCopies: IWorkingCopy[]): Promise<void> {
	return this.withProgressAndCancellation(async () => {

		// Soft revert is good enough on shutdown
		const revertOptions = { soft: true };

		// First revert through the editor service if we revert all
		if (modifiedWorkingCopies.length === this.workingCopyService.modifiedCount) {
			await this.editorService.revertAll(revertOptions);
		}

		// If we still have modified working copies, revert those directly
		await Promises.settled(modifiedWorkingCopies.map(workingCopy => workingCopy.isModified() ? workingCopy.revert(revertOptions) : Promise.resolve()));
	}, localize('revertBeforeShutdown', "Reverting editors with unsaved changes is taking a bit longer..."));
}

