CommandsRegistry.registerCommand('_remoteCLI.manageExtensions', async function (accessor: ServicesAccessor, args: ManageExtensionsArgs): Promise<string | undefined> {
	const instantiationService = accessor.get(IInstantiationService);
	const extensionManagementServerService = accessor.get(IExtensionManagementServerService);
	const remoteExtensionManagementService = extensionManagementServerService.remoteExtensionManagementServer?.extensionManagementService;
	if (!remoteExtensionManagementService) {
		return;
	}

	const lines: string[] = [];
	const logger = new class extends AbstractMessageLogger {
		protected override log(level: LogLevel, message: string): void {
			lines.push(message);
		}
	}();
	const childInstantiationService = instantiationService.createChild(new ServiceCollection([IExtensionManagementService, remoteExtensionManagementService]));
	try {
		const cliService = childInstantiationService.createInstance(RemoteExtensionManagementCLI, logger);

		if (args.list) {
			await cliService.listExtensions(!!args.list.showVersions, args.list.category, undefined);
		} else {
			const revive = (inputs: (string | UriComponents)[]) => inputs.map(input => isString(input) ? input : URI.revive(input));
			if (Array.isArray(args.install) && args.install.length) {
				try {
					await cliService.installExtensions(revive(args.install), [], { isMachineScoped: true }, !!args.force);
				} catch (e) {
					lines.push(e.message);
				}
			}
			if (Array.isArray(args.uninstall) && args.uninstall.length) {
				try {
					await cliService.uninstallExtensions(revive(args.uninstall), !!args.force, undefined);
				} catch (e) {
					lines.push(e.message);
				}
			}
		}
		return lines.join('\n');
	} finally {
		childInstantiationService.dispose();
	}

});

class RemoteExtensionManagementCLI extends ExtensionManagementCLI {

	private _location: string | undefined;

	constructor(
		logger: ILogger,
		@IExtensionManagementService extensionManagementService: IExtensionManagementService,
		@IExtensionGalleryService extensionGalleryService: IExtensionGalleryService,
		@ILabelService labelService: ILabelService,
		@IWorkbenchEnvironmentService envService: IWorkbenchEnvironmentService,
		@IExtensionManifestPropertiesService private readonly _extensionManifestPropertiesService: IExtensionManifestPropertiesService,
		@IProductService productService: IProductService,
	) {
		super([], logger, extensionManagementService, extensionGalleryService, productService);

		const remoteAuthority = envService.remoteAuthority;
		this._location = remoteAuthority ? labelService.getHostLabel(Schemas.vscodeRemote, remoteAuthority) : undefined;
	}

	protected override get location(): string | undefined {
		return this._location;
	}

	protected override validateExtensionKind(manifest: IExtensionManifest): boolean {
		if (!this._extensionManifestPropertiesService.canExecuteOnWorkspace(manifest)
			// Web extensions installed on remote can be run in web worker extension host
			&& !(isWeb && this._extensionManifestPropertiesService.canExecuteOnWeb(manifest))) {
			this.logger.info(localize('cannot be installed', "Cannot install the '{0}' extension because it is declared to not run in this setup.", getExtensionId(manifest.publisher, manifest.name)));
			return false;
		}
		return true;
	}
}

const targetRequestId = isRequestVM(item) ? item.id : isResponseVM(item) ? item.requestId : undefined;
if (!targetRequestId) {
	return;
}

// Check if this is a contributed session that supports forking
const contentProviderSchemes = chatSessionsService.getContentProviderSchemes();
if (contentProviderSchemes.includes(getChatSessionType(sessionResource))) {
	const contributedSession = await chatSessionsService.getOrCreateChatSession(sessionResource, CancellationToken.None);
	let request = contributedSession.history.find((entry): entry is IChatSessionRequestHistoryItem => entry.type === 'request' && entry.id === targetRequestId);
	if (!request) {
		const chatModel = chatService.getSession(sessionResource);
		const serializedData = chatModel?.toJSON();
		for (const [, entry] of serializedData?.requests.entries() ?? []) {
			if (entry.requestId === targetRequestId) {
				request = {
					id: entry.requestId,
					type: 'request',
					prompt: typeof entry.message === 'string' ? entry.message : entry.message.text,
					participant: entry.agent?.id ?? '',
					variableData: entry.variableData,
					modelId: entry.modelId,
				};
				break;
			}
		}
	}
	if (await this._tryForkAsChat(instantiationService, sessionResource, request)) {
		return;
	}
	return await this.forkContributedChatSession(sessionResource, request, true, chatSessionsService, instantiationService);
}

const chatModel = chatService.getSession(sessionResource);
if (!chatModel) {
	return;
}

// Export the full session data and truncate to include only requests up to and including the target
const serializedData = chatModel.toJSON();
const isRequestItem = isRequestVM(item);
let targetIndex = -1;
if (widget?.viewModel) {
	let requestIndex = -1;
	for (const entry of widget.viewModel.getItems()) {
		if (isRequestVM(entry)) {
			requestIndex += 1;
		}
		if (entry.id === item?.id) {
			targetIndex = isRequestVM(entry) ? Math.max(0, requestIndex - 1) : requestIndex;
			break;
		}
	}
}
if (targetIndex < 0) {
	const requestIndex = chatModel.getRequests().findIndex(r => r.id === targetRequestId);
	targetIndex = isRequestItem ? Math.max(0, requestIndex - 1) : requestIndex;
}
if (targetIndex < 0) {
	return;
}

const forkedData = revive(JSON.parse(JSON.stringify({
	...serializedData,
	requests: serializedData.requests.slice(0, targetIndex + 1),
}))) as ISerializableChatData;
forkedData.sessionId = generateUuid();
const forkedTimestamp = Date.now();
forkedData.creationDate = forkedTimestamp;
forkedData.customTitle = chatModel.title.startsWith(forkedTitlePrefix)
	? chatModel.title
	: localize('chat.forked.title', "Forked: {0}", chatModel.title);
for (const [index, req] of forkedData.requests.entries()) {
	req.shouldBeRemovedOnSend = undefined;
	req.isHidden = undefined;
	// Generate fresh IDs so the tree doesn't reuse stale DOM from the source session
	req.requestId = generateUuid();
	req.responseId = req.responseId ? generateUuid() : undefined;
	req.timestamp = forkedTimestamp + index;
	if (req.response) {
		req.modelState = { value: ResponseModelState.Complete, completedAt: forkedTimestamp + index };
	}
}

const modelRef = chatService.loadSessionFromData(forkedData, 'ChatForkActions#forkSession', 'currentSession');

